import sys
import json
import pandas as pd
import numpy as np

def to_float(x):
    return float(np.round(x, 2))

def to_pct(x):
    return float(np.round(x, 1))

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- Totals ----
    rev_tw_total = df['Revenue_TW'].dropna().sum()
    rev_lw_total = df['Revenue_LW'].dropna().sum()
    rev_ly_total = df['Revenue_LY'].dropna().sum()
    units_tw_total = df['Units_TW'].dropna().sum()
    units_lw_total = df['Units_LW'].dropna().sum()
    orders_tw_total = df['Orders_TW'].dropna().sum()
    orders_lw_total = df['Orders_LW'].dropna().sum()

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw_total),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw_total),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(rev_ly_total),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw_total),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw_total),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw_total),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw_total),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw_total and not np.isnan(rev_lw_total) and rev_lw_total != 0:
        wow_total = (rev_tw_total - rev_lw_total) / rev_lw_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_pct(wow_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly_total and not np.isnan(rev_ly_total) and rev_ly_total != 0:
        yoy_total = (rev_tw_total - rev_ly_total) / rev_ly_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_pct(yoy_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top entities by Revenue_TW ----
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(3)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW"
        })

    # ---- Top WoW gainers and losers ----
    wow_df = df.dropna(subset=['WoW_Pct'])
    top_wow_gain = wow_df.sort_values('WoW_Pct', ascending=False).head(3)
    top_wow_loss = wow_df.sort_values('WoW_Pct', ascending=True).head(3)

    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": to_pct(row['WoW_Pct']),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    for _, row in top_wow_loss.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": to_pct(row['WoW_Pct']),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top YoY gainers and losers ----
    yoy_df = df.dropna(subset=['YoY_Pct'])
    top_yoy_gain = yoy_df.sort_values('YoY_Pct', ascending=False).head(3)
    top_yoy_loss = yoy_df.sort_values('YoY_Pct', ascending=True).head(3)

    for _, row in top_yoy_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": to_pct(row['YoY_Pct']),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    for _, row in top_yoy_loss.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": to_pct(row['YoY_Pct']),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Ensure all values are plain python floats (already done via to_float/to_pct)
    print(json.dumps(facts[:25]))

if __name__ == "__main__":
    main()
